/**
 * Schema migration runner over the vendored upstream migrations (packages/db/migrations/*.sql,
 * generated by scripts/gen-migrations.mjs). Needs neither the upstream submodule nor TypeORM.
 *
 * Bookkeeping uses TypeORM's own `migrations` table (id / timestamp / name), so a database
 * migrated here and one migrated by upstream `pnpm migrate` are interchangeable: either tool
 * applies only what the other has not.
 *
 * Node-only (reads the SQL files); not for Workers.
 */
import { readdirSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const MIGRATIONS_DIR = resolve(dirname(fileURLToPath(import.meta.url)), "../migrations");

export type Migration = {
  /** TypeORM migration name, e.g. `Init1000000000000` (what `migrations.name` holds). */
  name: string;
  /** Last 13 digits of the name (TypeORM's ordering key). */
  timestamp: number;
  file: string;
  sql: string;
};

/** Minimal client: `pg` Client / PoolClient and PGlite both fit. Multi-statement text must be accepted when `params` is omitted. */
export type MigrationClient = {
  query: (sql: string, params?: unknown[]) => Promise<{ rows: Record<string, unknown>[] }>;
};

export type AppliedMigration = { name: string; timestamp: number };

/** Same DDL TypeORM issues when it creates its bookkeeping table. */
export const MIGRATIONS_TABLE_DDL = `CREATE TABLE IF NOT EXISTS "migrations" ("id" SERIAL NOT NULL, "timestamp" bigint NOT NULL, "name" character varying NOT NULL, CONSTRAINT "PK_8c82d7f526340ab734260ea46be" PRIMARY KEY ("id"))`;

/** Session-level advisory lock key so two runners never interleave. */
const LOCK_KEY = 7_420_731_802;

export function loadMigrations(dir: string = MIGRATIONS_DIR): Migration[] {
  const list = readdirSync(dir)
    .filter((f) => f.endsWith(".sql"))
    .map((file) => {
      const sql = readFileSync(resolve(dir, file), "utf8");
      const name = /^-- name: (\S+)$/m.exec(sql)?.[1];
      if (!name) throw new Error(`migrate: ${file} has no "-- name:" header`);
      const ts = /(\d{13})$/.exec(name)?.[1];
      if (!ts) throw new Error(`migrate: ${name} does not end in a 13-digit timestamp`);
      return { name, timestamp: Number(ts), file, sql };
    });
  // TypeORM orders by the timestamp in the name (not the file name, which can differ).
  list.sort((a, b) => a.timestamp - b.timestamp || a.name.localeCompare(b.name));
  const names = new Set<string>();
  for (const m of list) {
    if (names.has(m.name)) throw new Error(`migrate: duplicate migration ${m.name}`);
    names.add(m.name);
  }
  return list;
}

export async function hasMigrationsTable(client: MigrationClient): Promise<boolean> {
  const r = await client.query(`SELECT to_regclass('"migrations"') IS NOT NULL AS "exists"`);
  return r.rows[0]?.exists === true;
}

export async function appliedMigrations(client: MigrationClient): Promise<AppliedMigration[]> {
  if (!(await hasMigrationsTable(client))) return [];
  const r = await client.query(`SELECT "timestamp", "name" FROM "migrations" ORDER BY "id" ASC`);
  return r.rows.map((row) => ({ name: String(row.name), timestamp: Number(row.timestamp) }));
}

export type MigrationPlan = {
  applied: AppliedMigration[];
  pending: Migration[];
  /** Applied in the database but not vendored here (the database is ahead of this checkout). */
  unknown: AppliedMigration[];
  /** Pending migrations older than the newest applied one (TypeORM would still run them). */
  outOfOrder: Migration[];
};

export function planMigrations(all: Migration[], applied: AppliedMigration[]): MigrationPlan {
  const done = new Set(applied.map((a) => a.name));
  const known = new Set(all.map((m) => m.name));
  const pending = all.filter((m) => !done.has(m.name));
  const newest = applied.reduce((max, a) => Math.max(max, a.timestamp), 0);
  return {
    applied,
    pending,
    unknown: applied.filter((a) => !known.has(a.name)),
    outOfOrder: pending.filter((m) => m.timestamp < newest),
  };
}

export type MigrateOptions = {
  /** Called before each migration runs. */
  onApply?: (m: Migration) => void;
  /** Apply even when the database has migrations this checkout does not know. */
  allowUnknown?: boolean;
};

/**
 * Apply every pending migration in order, one transaction per migration (the `migrations`
 * row is written in the same transaction). Returns the applied migrations.
 */
export async function migrate(client: MigrationClient, all: Migration[] = loadMigrations(), opts: MigrateOptions = {}): Promise<Migration[]> {
  await client.query(`SELECT pg_advisory_lock(${LOCK_KEY})`);
  try {
    await client.query(MIGRATIONS_TABLE_DDL);
    const plan = planMigrations(all, await appliedMigrations(client));
    if (plan.unknown.length > 0 && !opts.allowUnknown) {
      throw new Error(
        `migrate: the database has ${plan.unknown.length} migration(s) this checkout does not know (newest: ${plan.unknown[plan.unknown.length - 1].name}). ` +
          "Update packages/db/migrations (scripts/gen-migrations.mjs) or pass allowUnknown.",
      );
    }
    const done: Migration[] = [];
    for (const m of plan.pending) {
      opts.onApply?.(m);
      await client.query("BEGIN");
      try {
        await client.query(m.sql);
        await client.query(`INSERT INTO "migrations" ("timestamp", "name") VALUES ($1, $2)`, [m.timestamp, m.name]);
        await client.query("COMMIT");
      } catch (e) {
        await client.query("ROLLBACK");
        throw new Error(`migrate: ${m.name} (${m.file}) failed: ${e instanceof Error ? e.message : String(e)}`, { cause: e });
      }
      done.push(m);
    }
    return done;
  } finally {
    await client.query(`SELECT pg_advisory_unlock(${LOCK_KEY})`);
  }
}

/**
 * A self-contained SQL script that applies `migrations` in order, for hosts where only a SQL
 * console / `psql -f` reaches the database. Each migration runs in its own transaction and is
 * skipped when `migrations` already records it, so the script is safe to re-run.
 */
export function renderMigrationScript(migrations: Migration[]): string {
  const parts = [
    "-- Generated by `pnpm db:migrate sql`. Run with: psql -v ON_ERROR_STOP=1 -f <file>",
    `${MIGRATIONS_TABLE_DDL};`,
    "",
  ];
  for (const m of migrations) {
    const body = m.sql.replace(/^(?:-- (?:Generated by|name:) .*\n)+\n?/, "").trim();
    if (body.includes("$mk_sql$")) throw new Error(`migrate: ${m.name} contains the $mk_sql$ quote tag`);
    parts.push(
      `-- ${m.name}`,
      "BEGIN;",
      "DO $mk$ BEGIN",
      `  IF NOT EXISTS (SELECT 1 FROM "migrations" WHERE "name" = '${m.name}') THEN`,
      `    EXECUTE $mk_sql$${body}$mk_sql$;`,
      `    INSERT INTO "migrations" ("timestamp", "name") VALUES (${m.timestamp}, '${m.name}');`,
      "  END IF;",
      "END $mk$;",
      "COMMIT;",
      "",
    );
  }
  return parts.join("\n");
}
